mapper.insert:
insert into review(user_id, product_id, order_id, rating, content, images,
                   status, create_time, update_time)
select #{userId}, #{review.productId}, o.id, #{review.rating}, #{review.content},
       #{review.images}, 1, now(3), now(3)
from orders o
where o.id = #{review.orderId}
  and o.user_id = #{userId}
  and o.status = 4
  and exists (
      select 1 from order_detail d
      where d.order_id = o.id and d.product_id = #{review.productId}
  )

mapper.select:
select r.id, r.order_id as orderId, r.product_id as productId, r.rating,
       r.content, r.images, r.status, r.create_time as createTime,
       p.name as productName
from review r
left join product p on p.id = r.product_id
where r.order_id = #{orderId}
  and r.product_id = #{productId}
  and r.user_id = #{userId}
limit 1

select count(*)
from review
where order_id = #{orderId}
  and product_id = #{productId}
  and user_id = #{userId}

select r.id, r.rating, r.content, r.images, r.create_time as createTime, u.name as displayName from review r left join user u on u.id = r.user_id where r.product_id = #{productId} and r.status = 1
and r.rating <= 3 and r.rating = #{rating}
order by r.create_time desc

select * from review
where order_id = #{orderId} and user_id = #{userId}
limit 1
